import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import InsuranceBenefitsList from './insuranceBenefitstList/InsuranceBenefitsList';
import InsuranceBenefitsStatistics from './insuranceBenefitstList/InsuranceBenefitsStatistics';
import type { Insurance } from '@/types/insurance.types';

export default function InsuranceBenfits() {
    const [insuranceId, setInsuranceId] = useState<string | undefined>();

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.insurance.employeeMe });
                const data = res.data?.data as Insurance | undefined;
                if (!cancelled && data?.id != null) setInsuranceId(String(data.id));
            } catch {
                if (!cancelled) setInsuranceId(undefined);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    return (
        <div className="w-full mt-6">
            <InsuranceBenefitsStatistics />
            <InsuranceBenefitsList insuranceId={insuranceId} />
        </div>
    );
}
