import { format } from 'date-fns';
import type { EmployeeAttendanceType } from '@/features/humanResources/types/employeeAttendance.types';
import type { EmployeeApi } from './types';
import { displayValue } from './utils';
import { InsuranceHeadingDataRow } from './InsuranceHeadingDataRow';
import { InsuranceHeadingSection } from './InsuranceHeadingSection';

type AttendanceSummary = EmployeeAttendanceType['summary'];

export function InsuranceEmployeeDetailSections({
    employee,
    summary,
}: {
    employee: EmployeeApi;
    summary: AttendanceSummary | undefined;
}) {
    return (
        <div className="mt-6 space-y-6">
            {/* صف 1: عمودان */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <InsuranceHeadingSection title="البيانات الأساسية" className="!mt-0">
                    <InsuranceHeadingDataRow label="الاسم الكامل" value={displayValue(employee.name)} />
                    <InsuranceHeadingDataRow label="تاريخ الميلاد" value={displayValue(employee.birth_date)} />
                    <InsuranceHeadingDataRow label="رقم الهوية" value={displayValue(employee.id_number)} />
                    <InsuranceHeadingDataRow label="العنوان" value={displayValue(employee.address)} />
                    <InsuranceHeadingDataRow label="الهاتف" value={displayValue(employee.phone_number)} />
                    <InsuranceHeadingDataRow label="البريد الإلكتروني" value={displayValue(employee.email)} />
                </InsuranceHeadingSection>

                <InsuranceHeadingSection title="البيانات الوظيفية" className="!mt-0">
                    <InsuranceHeadingDataRow label="معرّف الموظف" value={displayValue(employee.id)} />
                    <InsuranceHeadingDataRow
                        label="الفرع"
                        value={displayValue(employee.branch_name ?? employee.branch_id)}
                    />
                    <InsuranceHeadingDataRow label="القسم" value={displayValue(employee.department)} />
                    <InsuranceHeadingDataRow
                        label="الدرجة الوظيفية"
                        value={displayValue(employee.position_name ?? employee.position)}
                    />
                    <InsuranceHeadingDataRow label="نوع التعاقد" value={displayValue(employee.contract_type)} />
                    <InsuranceHeadingDataRow
                        label="تاريخ التعيين"
                        value={employee.created_at ? format(employee.created_at, 'yyyy-MM-dd') : '—'}
                    />
                </InsuranceHeadingSection>
            </div>

            {/* العقد */}
            <InsuranceHeadingSection title="بيانات العقد" className="">
                <InsuranceHeadingDataRow
                    label="تاريخ بداية العقد"
                    value={
                        employee.contract_start_date
                            ? employee.contract_start_date
                            : employee.created_at
                              ? format(employee.created_at, 'yyyy-MM-dd')
                              : '—'
                    }
                />
                <InsuranceHeadingDataRow
                    label="تاريخ التوقيع"
                    value={displayValue(employee.contract_sign_date)}
                />
                <InsuranceHeadingDataRow
                    label="تاريخ نهاية العقد"
                    value={
                        employee.contract_end_date
                            ? employee.contract_end_date
                            : employee.updated_at
                              ? format(employee.updated_at, 'yyyy-MM-dd')
                              : '—'
                    }
                />
                <InsuranceHeadingDataRow label="العنوان" value={displayValue(employee.address)} />
                <InsuranceHeadingDataRow label="الهاتف" value={displayValue(employee.phone_number)} />
                <InsuranceHeadingDataRow label="البريد الإلكتروني" value={displayValue(employee.email)} />
            </InsuranceHeadingSection>

            {/* صف 3: ثلاثة أعمدة */}
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                <InsuranceHeadingSection title="المؤهلات" className="!mt-0">
                    <InsuranceHeadingDataRow label="الدرجة العلمية" value={displayValue(employee.education_degree)} />
                    <InsuranceHeadingDataRow label="الجامعة" value={displayValue(employee.university)} />
                    <InsuranceHeadingDataRow label="التخصص" value={displayValue(employee.specialization)} />
                </InsuranceHeadingSection>

                <InsuranceHeadingSection title="الراتب" className="!mt-0">
                    <InsuranceHeadingDataRow
                        label="الراتب الأساسي"
                        value={
                            employee.main_salary != null && employee.main_salary !== ''
                                ? `${displayValue(employee.main_salary)} ر.س`
                                : '—'
                        }
                    />
                    <InsuranceHeadingDataRow label="الراتب الإضافي" value="—" />
                    <InsuranceHeadingDataRow label="المكافآت" value="—" />
                </InsuranceHeadingSection>

                <InsuranceHeadingSection title="الترقيات" className="!mt-0 md:col-span-2 xl:col-span-1">
                    <InsuranceHeadingDataRow
                        label="الدرجة الحالية"
                        value={displayValue(employee.last_position ?? employee.position_name ?? employee.position)}
                    />
                    <InsuranceHeadingDataRow label="الترقية القادمة" value={displayValue(employee.next_upgrade)} />
                    <InsuranceHeadingDataRow
                        label="تاريخ الترقية"
                        value={employee.updated_at ? format(employee.updated_at, 'yyyy-MM-dd') : '—'}
                    />
                </InsuranceHeadingSection>
            </div>

            {/* */}
            <InsuranceHeadingSection title="ملخص الحضور والإجازات" className="">
                {summary ? (
                    <>
                        <InsuranceHeadingDataRow label="إجمالي الأيام" value={displayValue(summary.total_days)} />
                        <InsuranceHeadingDataRow label="أيام الحضور" value={displayValue(summary.present)} />
                        <InsuranceHeadingDataRow label="أيام الغياب" value={displayValue(summary.absent)} />
                        <InsuranceHeadingDataRow label="التأخير" value={displayValue(summary.late)} />
                        <InsuranceHeadingDataRow label="أيام الإجازة" value={displayValue(summary.leave)} />
                    </>
                ) : (
                    <p className="px-4 py-6 text-sm text-white-blue-700 text-center">
                        لا تتوفر بيانات حضور وإجازات حالياً.
                    </p>
                )}
            </InsuranceHeadingSection>
        </div>
    );
}
