import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { Button } from '@/components/ui/button';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import FileDownloadIcon from '@/components/icons/file/FileDownloadIcon';
import type { EmployeeApi } from './types';
import { API_GATEWAY_BASE_URL } from '@/core/global-data/constants.data';

export function InsurancePageHeader({ employee }: { employee: EmployeeApi | null }) {
    const navigate = useNavigate();

    const handleDownloadContract = () => {
        const path = employee?.attachment;
        if (path && typeof path === 'string') {
            const url = path.startsWith('http')
                ? path
                : `${(API_GATEWAY_BASE_URL || '').replace(/\/$/, '')}/${path.replace(/^\//, '')}`;
            window.open(url, '_blank', 'noopener,noreferrer');
            return;
        }
        toast('لا يوجد ملف عقد متاح للتنزيل حالياً.');
    };

    return (
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <UnderlineHeading text="بيانات الموظف" />
            <div className="flex flex-wrap items-center gap-3 justify-end">
                <Button
                    type="button"
                    variant="outline"
                    onClick={() => navigate('/')}
                    className="h-10 rounded-md border-white-blue-300 bg-white text-primery-blue-900 hover:bg-white-blue-50 font-cairo gap-2"
                >
                    <ArrowBackIcon className="text-primery-blue-500" />
                    العودة
                </Button>
                <Button
                    type="button"
                    variant="outline"
                    onClick={handleDownloadContract}
                    className="h-10 rounded-md border-primery-blue-500 text-primery-blue-500 bg-white hover:bg-primery-blue-50 font-cairo gap-2"
                >
                    <FileDownloadIcon />
                    تنزيل العقد
                </Button>
            </div>
        </div>
    );
}
