import type { ReactNode } from 'react';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { cn } from '@/lib/utils';

export function InsuranceHeadingSection({
    title,
    children,
    className,
}: {
    title: string;
    children: ReactNode;
    className?: string;
}) {
    return (
        <div className={cn('mt-8', className)}>
            <UnderlineHeading text={title} />
            <div className="mt-3 w-full rounded-lg border border-white-blue-300 overflow-hidden bg-white">{children}</div>
        </div>
    );
}
