import { useEffect, useMemo, useState } from 'react';
import Cookies from 'js-cookie';
import { LoadingSpinner } from '@/components/Loading/LoadingSpinner';
import { useAppSelector } from '@/core/global-store';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { EmployeeAttendanceType } from '@/features/humanResources/types/employeeAttendance.types';
import defaultAvatar from '@/assets/imgs/user.png';
import {
    type EmployeeApi,
    flattenMePayload,
    idFromUnknown,
    InsuranceEmployeeDetailSections,
    InsurancePageHeader,
    InsuranceProfileHero,
    resolveImageUrl,
    resolvePerformancePercent,
    toDisplayEmployee,
} from './insuranceHeading';

export default function Heading() {
    const authUser = useAppSelector((state) => state.auth.user);
    const me = useAppSelector((state) => state.auth.me);

    const cookieUserId = useMemo(() => {
        try {
            const u = JSON.parse(Cookies.get('user') || '{}') as { id?: number };
            return u?.id;
        } catch {
            return undefined;
        }
    }, []);

    const employeeId =
        idFromUnknown(flattenMePayload(me).id) ?? authUser?.id ?? cookieUserId;

    const [employee, setEmployee] = useState<EmployeeApi | null>(null);
    const [attendance, setAttendance] = useState<EmployeeAttendanceType | null>(null);
    const [loading, setLoading] = useState(true);
    const [fetchError, setFetchError] = useState<string | null>(null);

    useEffect(() => {
        if (employeeId == null) {
            setLoading(false);
            setFetchError(null);
            return;
        }

        let cancelled = false;

        const load = async () => {
            setLoading(true);
            setFetchError(null);

            try {
                const empRes = await apiGet({ endpoint: endpoints.employee.show + employeeId });

                if (cancelled) return;
                setEmployee((empRes.data?.data as EmployeeApi) ?? null);

                try {
                    const attRes = await apiGet({
                        endpoint: endpoints.employeeAttendance.attendance,
                        queryParams: { employee_id: String(employeeId) },
                    });
                    if (!cancelled) {
                        const list = attRes.data?.data;
                        setAttendance(Array.isArray(list) && list[0] ? list[0] : null);
                    }
                } catch {
                    if (!cancelled) setAttendance(null);
                }
            } catch {
                if (!cancelled) {
                    setEmployee(null);
                    setFetchError('تعذر تحميل بيانات الموظف من الخادم؛ سيتم عرض البيانات المتوفرة من حسابك.');
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        };

        load();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    const displayEmployee = useMemo(
        () => toDisplayEmployee(authUser, me, employee, cookieUserId),
        [authUser, me, employee, cookieUserId]
    );

    const avatarSrc = resolveImageUrl(displayEmployee?.personal_image) ?? defaultAvatar;
    const summary = attendance?.summary;

    const performancePercent = useMemo(() => {
        if (!displayEmployee) return 0;
        return resolvePerformancePercent(displayEmployee, summary);
    }, [displayEmployee, summary]);

    if (loading) {
        return (
            <div className="mb-6 flex justify-center py-16">
                <LoadingSpinner />
            </div>
        );
    }

    if (!displayEmployee) {
        return (
            <div className="mb-6 rounded-2xl border border-red-error-100 bg-red-error-50 px-6 py-8 text-center text-red-error-600">
                تعذر تحديد الموظف. يرجى تسجيل الدخول مرة أخرى.
            </div>
        );
    }

    return (
        <div className="mb-6">
            {fetchError && (
                <p className="mb-4 rounded-lg border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-900">
                    {fetchError}
                </p>
            )}

            <InsurancePageHeader employee={displayEmployee} />

            <InsuranceProfileHero
                avatarSrc={avatarSrc}
                employee={displayEmployee}
                performancePercent={performancePercent}
            />

            <InsuranceEmployeeDetailSections employee={displayEmployee} summary={summary} />
        </div>
    );
}
