import { cn } from '@/lib/utils';
import InsuranceInfo from './InsuranceInfo';
import InsuranceCertificateRequest from './InsuranceCertificateRequest';
import InsuranceBenfits from './InsuranceBenefits';
import { useSearchParams } from 'react-router-dom';

type InsuranceTab = 'insurance' | 'certificate' | 'benefits';

export default function SelectabelContent() {
    const [searchParams, setSearchParams] = useSearchParams();
    const insuranceParam = searchParams.get('insurance');

    const activeTab: InsuranceTab = insuranceParam
        ? 'insurance'
        : searchParams.get('tab') === 'certificate'
          ? 'certificate'
          : searchParams.get('tab') === 'benefits'
            ? 'benefits'
            : 'insurance';

    const handleSelect = (value: InsuranceTab) => {
        setSearchParams(
            (prev) => {
                const next = new URLSearchParams(prev);
                if (value === 'insurance') {
                    next.delete('tab');
                    next.delete('insurance');
                } else if (value === 'certificate') {
                    next.set('tab', 'certificate');
                    next.delete('insurance');
                } else {
                    next.set('tab', 'benefits');
                    next.delete('insurance');
                }
                return next;
            },
            { replace: true },
        );
    };

    return (
        <div className="w-full mt-6">
            <div className="w-full flex flex-row items-center gap-[1px]">
                <button
                    type="button"
                    onClick={() => handleSelect('insurance')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-s-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'insurance',
                            'bg-primery-blue-400': activeTab !== 'insurance',
                        },
                    )}
                >
                    بيانات التأمينات
                </button>
                <button
                    type="button"
                    onClick={() => handleSelect('certificate')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal',
                        {
                            'bg-primery-blue-700': activeTab === 'certificate',
                            'bg-primery-blue-400': activeTab !== 'certificate',
                        },
                    )}
                >
                    طلب شهادة التأمينات
                </button>
                <button
                    type="button"
                    onClick={() => handleSelect('benefits')}
                    className={cn(
                        'w-full transition-colors text-base py-3 text-white-blue-50 font-bold leading-[120%] tracking-normal rounded-e-lg',
                        {
                            'bg-primery-blue-700': activeTab === 'benefits',
                            'bg-primery-blue-400': activeTab !== 'benefits',
                        },
                    )}
                >
                    مستحقات التأمينات
                </button>
            </div>
            {activeTab === 'insurance' && <InsuranceInfo />}
            {activeTab === 'certificate' && <InsuranceCertificateRequest />}
            {activeTab === 'benefits' && <InsuranceBenfits />}
        </div>
    );
}
