import { useCallback, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { InsuranceRelatives } from '@/types/insurance.types';

type InsuranceBenefitsListProps = {
    insuranceId?: string;
};

export default function InsuranceBenefitsList({ insuranceId }: InsuranceBenefitsListProps) {
    const [data, setData] = useState<InsuranceRelatives[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(
        async (options: FetchDataOptions) => {
            const policyId = insuranceId;
            if (!policyId) {
                setData([]);
                setPageCount(1);
                setTotalCount(0);
                return;
            }
            setIsLoading(true);
            try {
                const queryParams: Record<string, string | number | boolean> = {
                    page: options.pageIndex + 1,
                    pageSize: options.pageSize,
                    insurance_id: policyId,
                    ...options.filters,
                };
                if (options.globalFilter) {
                    queryParams.search = options.globalFilter;
                }
                const response = await apiGet({
                    endpoint: endpoints.insuranceRelatives.paginate,
                    queryParams,
                });
                const body = response.data.data;
                const perPage = body.pagination?.per_page || options.pageSize;
                setData(body.data ?? []);
                setPageCount(Math.max(1, Math.ceil((body.pagination?.total ?? 0) / perPage)));
                setTotalCount(body.pagination?.total ?? 0);
            } catch (error) {
                console.error('Error fetching data:', error);
                setData([]);
            } finally {
                setIsLoading(false);
            }
        },
        [insuranceId],
    );
    return (
        <div className="mt-6 mb-20 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
