import CircularProgress from '@/components/circles/CircularProgress';
import type { EmployeeApi } from './types';
import { displayValue, performanceBadgeLabel, workTypeLabel } from './utils';

export function InsuranceProfileHero({
    avatarSrc,
    employee,
    performancePercent,
}: {
    avatarSrc: string;
    employee: EmployeeApi;
    performancePercent: number;
}) {
    const badge = performanceBadgeLabel(performancePercent);

    return (
        <div className="w-full px-4 py-6 md:px-6 md:py-8 bg-primery-blue-800 text-white-blue-50 rounded-2xl mt-6 flex flex-col gap-8 lg:flex-row lg:items-center lg:justify-between">
            {/* RTL:*/}
            <div className="flex items-center gap-5 shrink-0 justify-center lg:justify-start">
                <div className="w-[140px] h-[140px] md:w-[180px] md:h-[180px] rounded-full overflow-hidden border-4 border-white/25 shadow-lg shrink-0 bg-white/10">
                    <img src={avatarSrc} alt="" className="w-full h-full object-cover" />
                </div>
            </div>

            <div className="flex-1 min-w-0 flex flex-col gap-4 text-center lg:text-start">
                <p className="text-lg md:text-xl lg:text-2xl font-bold leading-snug break-words">
                    <span className="text-white-blue-300 font-semibold">الاسم : </span>
                    {displayValue(employee.name)}
                </p>
                <p className="text-base md:text-lg leading-relaxed">
                    <span className="text-white-blue-300 font-medium">نوع الدوام : </span>
                    {workTypeLabel(employee)}
                </p>
            </div>

            <div className="flex flex-col items-center justify-center gap-2 shrink-0 lg:ps-4">
                <p className="text-sm font-medium text-white-blue-50 tracking-normal">معدل الأداء</p>
                <CircularProgress
                    percentage={performancePercent}
                    size={88}
                    textClassName="text-white-blue-50"
                    progressClassName="stroke-white-blue-50"
                    backgroundClassName="stroke-white-blue-700"
                />
                <p className="text-xs font-medium border border-white-blue-50 px-2 py-1 rounded-md mt-1">
                    {badge}
                </p>
            </div>
        </div>
    );
}
